contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking parameters to drive the contract
    function run(uint deposit1, uint withdrawGasless) public payable {
        require(address(this).balance >= deposit1);

        // 1) send Ether to c via its fallback to increase balances[msg.sender]
        c.f{value: deposit1}();

        // read the recorded balance for this test contract (msg.sender for c is this contract)
        uint beforeBal = c.balances(address(this));
        // also record c's Ether balance before withdraw
        uint cBalanceBefore = address(c).balance;

        // attempt withdraw and detect revert
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = c.balances(address(this));
        uint cBalanceAfter = address(c).balance;

        // General rule: if withdraw did not revert then the contract's stored balance for caller is zero
        // and the contract's Ether balance decreased by at least the recorded amount before (monotone decrease)
        // If it reverted, no expectation about balances (but the assertion must be general for all inputs)
        assert(reverted || (afterBal == 0 && cBalanceAfter + beforeBal <= cBalanceBefore));
    }

    // receive to accept refunds if any
    receive() external payable {}
}

