contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: send some deposits from this contract to c, then call withdraw and assert invariant
    function run(uint256 deposit1, uint256 deposit2) public payable {
        require(address(this).balance >= deposit1 + deposit2);
        // deposit two separate amounts via fallback by sending Ether
        c.f{value: deposit1}();
        c.f{value: deposit2}();

        // read balance recorded for this contract in c before withdraw
        uint256 beforeRecorded = c.balances(address(this));
        // record contract balances (Ether) before withdraw
        uint256 cBalanceBefore = address(c).balance;
        uint256 selfBefore = address(this).balance;

        // attempt withdraw and capture whether it reverted
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterRecorded = c.balances(address(this));
        uint256 cBalanceAfter = address(c).balance;
        uint256 selfAfter = address(this).balance;

        // If withdraw reverted, recorded balance must be unchanged and Ether balances unchanged.
        // If withdraw succeeded, recorded balance must be zero, and C's Ether decreased by the withdrawn amount
        // and this contract's Ether increased by the same amount.
        assert(
            (reverted && afterRecorded == beforeRecorded && cBalanceAfter == cBalanceBefore && selfAfter == selfBefore)
            || (!reverted && afterRecorded == 0 && cBalanceBefore >= cBalanceAfter && selfAfter >= selfBefore && (cBalanceBefore - cBalanceAfter) == (selfAfter - selfBefore) && (cBalanceBefore - cBalanceAfter) == beforeRecorded)
        );
    }

    // allow receiving Ether back from C.withdraw
    receive() external payable { }
}

