contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit 'depositAmount' into c via its fallback, then attempt withdraw.
    // The rule: after a successful withdraw, c.balances(address(this)) == 0 and address(c).balance <= beforeBalance - depositAmount;
    // if withdraw reverts, c.balances(address(this)) remains equal to the deposited amount.
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");
        // record balance of C before deposit
        uint256 beforeC = address(c).balance;
        // call fallback by sending Ether
        c.call{value: depositAmount}("");
        // read recorded balance in C for this contract
        uint256 recordedAfterDeposit = c.balances(address(this));
        // now attempt withdraw and capture whether it reverted
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 recordedAfter = c.balances(address(this));
        uint256 afterC = address(c).balance;
        // General rule: either withdraw succeeded and cleared our recorded balance to 0 and C's balance decreased by at least depositAmount,
        // or withdraw reverted and the recorded balance remains equal to what it was after deposit.
        assert(
            (!reverted && recordedAfter == 0 && afterC + depositAmount <= beforeC) ||
            (reverted && recordedAfter == recordedAfterDeposit)
        );
    }

    // Allow this contract to receive Ether so c.transfer/call can send to it during withdraw.
    receive() external payable {}
}

