    // The function is payable so the test contract can hold Ether beforehand if needed.
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Record C's balance before deposit
        uint256 beforeC = address(c).balance;

        // Perform deposit by calling C's fallback (send Ether)
        (bool depositSent, ) = address(c).call{value: depositAmount}("");
        require(depositSent, "deposit failed");

        // Read the recorded balance in C for this contract after deposit
        uint256 recordedAfterDeposit = c.balances(address(this));

        // Attempt withdraw and capture whether it reverted
        bool withdrew;
        try c.withdraw() {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // Read recorded balance and C's balance after withdraw attempt
        uint256 recordedAfter = c.balances(address(this));
        uint256 afterC = address(c).balance;

        // General rule assertion:
        // If withdraw succeeded: recorded balance for this becomes 0 and C's balance decreased by at least depositAmount (unless other external Ether flows, but in this single-actor test the decrease must be >= depositAmount).
        // If withdraw reverted: recorded balance remains equal to the post-deposit recorded amount.
        assert(
            (withdrew && recordedAfter == 0 && beforeC >= afterC + depositAmount) ||
            (!withdrew && recordedAfter == recordedAfterDeposit)
        );
    }

    // Allow this contract to receive Ether so C.withdraw can send to it.
    receive() external payable {}
}

