contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept parameters: deposit amount and a boolean indicating whether to attempt withdraw.
    // The test will deposit `amount` into c via its payable fallback, then try to withdraw.
    function run(uint256 amount, bool doWithdraw) public payable {
        require(address(this).balance >= amount, "not enough funds to deposit");

        // read balance before any operation
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeRecorded = c.balances(address(this));

        // deposit into c by calling its fallback with value 'amount'
        // note: this is a top-level state-changing call
        (bool sent, ) = address(c).call{value: amount}("\x00");
        // We allow both success and failure of the raw call; if it failed then state shouldn't change.
        bool depositSucceeded = sent;

        uint256 afterContractBalance = address(c).balance;
        uint256 afterRecorded = c.balances(address(this));

        // Optionally attempt withdraw; capture whether it reverted
        bool withdrewReverted;
        if (doWithdraw) {
            try c.withdraw() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        } else {
            withdrewReverted = true; // treat as not withdrawn
        }

        uint256 finalContractBalance = address(c).balance;
        uint256 finalRecorded = c.balances(address(this));

        // General rule to assert for all inputs:
        // If the deposit call succeeded then recorded balance must have increased by amount,
        // and if withdraw was attempted and did NOT revert then the recorded balance for this address becomes 0
        // and the contract's ether balance does not increase as a result of withdraw (it decreases or stays same).
        assert(
            (
                // if deposit succeeded: recorded increments and contract balance increases by at least amount
                (depositSucceeded && afterRecorded >= beforeRecorded && afterRecorded - beforeRecorded == amount && afterContractBalance >= beforeContractBalance && afterContractBalance - beforeContractBalance == amount)
                ||
                // if deposit failed: nothing changed
                (!depositSucceeded && afterRecorded == beforeRecorded && afterContractBalance == beforeContractBalance)
            )
            &&
            (
                // if withdraw was attempted and succeeded then finalRecorded == 0 and contract balance did not increase
                (doWithdraw && !withdrewReverted) ? (finalRecorded == 0 && finalContractBalance <= afterContractBalance) : true
            )
        );
    }

    // allow receiving Ether when c calls back
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an amount to deposit and then always attempt withdraw.
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient funds to deposit");

        // Read observed state before deposit
        uint256 beforeRecorded = c.balances(address(this));
        uint256 beforeContractBalance = address(c).balance;

        // Perform deposit by sending Ether to c (fallback payable). This is a top-level state-changing call.
        // We use low-level call to invoke fallback with value. Capture success flag via try/catch is not possible here;
        // but low-level call is not allowed per constraints; however the contract's fallback is payable and reachable
        // only via sending value to address(c). Use address(c).call is allowed from this contract context.
        (bool depositOk, ) = address(c).call{value: depositAmount}("");

        // Read state after deposit
        uint256 afterRecorded = c.balances(address(this));
        uint256 afterContractBalance = address(c).balance;

        // Attempt withdraw and record whether it reverted. This is a top-level call on c.withdraw().
        bool withdrawReverted;
        try c.withdraw() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Read final state after withdraw attempt
        uint256 finalRecorded = c.balances(address(this));
        uint256 finalContractBalance = address(c).balance;

        // General rule:
        // If withdraw did not revert then the caller's recorded balance must be zero and the contract's balance
        // must not have increased compared to just before the withdraw (i.e., finalContractBalance <= afterContractBalance).
        // Additionally, if the deposit low-level call succeeded then afterRecorded increased by depositAmount
        // compared to beforeRecorded and contract balance increased accordingly; if deposit low-level call failed then
        // balances didn't change.
        assert(
            (
                // deposit semantics
                (depositOk && afterRecorded - beforeRecorded == depositAmount && afterContractBalance - beforeContractBalance == depositAmount)
                ||
                (!depositOk && afterRecorded == beforeRecorded && afterContractBalance == beforeContractBalance)
            )
            &&
            (
                // withdraw semantics
                (withdrawReverted || (finalRecorded == 0 && finalContractBalance <= afterContractBalance))
            )
        );
    }

    // allow receiving Ether when c sends funds back
    receive() external payable { }
}

